// Demo: Software Prefetching — struct layout waste
var fields=[['a',1],['b',8],['c',1],['d',8],['e',4]];
var off=0;fields.forEach(function(f){var al=Math.min(f[1],8);off=Math.ceil(off/al)*al;off+=f[1];});
console.log('technique: Software Prefetching');console.log('naive order size: '+off+' bytes');
var srt=fields.slice().sort(function(a,b){return b[1]-a[1];});off=0;srt.forEach(function(f){var al=Math.min(f[1],8);off=Math.ceil(off/al)*al;off+=f[1];});
console.log('sorted-by-size order: '+off+' bytes — reorder fields, shrink structs');

